import AuditingPageHeader from "@/components/dashboard/auditing/auditing-page-header"
import AuditingFilter from "@/components/dashboard/auditing/auditing-filter"
import AuditingTable from "@/components/dashboard/auditing/auditing-table"
import { createClient } from "@/lib/supabase/server"
import { getPropertyActivityLogs, getPropertyActivityLogResources } from "@/lib/dashboard/queries"
import { getPropertyForUser } from "@/lib/dashboard/property-access"
import { resolveDashboardNavVisibility } from "@/lib/dashboard/dashboard-layout-context"
import { redirect } from "next/navigation"

type pageProps = {
    params: Promise<{ propertyId: string }>
    searchParams: Promise<{
        page?: string
        pageSize?: string
        q?: string
        action?: string
        resource?: string
        dateFrom?: string
        dateTo?: string
        sortBy?: string
        sortOrder?: string
        [key: string]: string | string[] | undefined
    }>
}

function isValidYmd(value: string): boolean {
    return /^\d{4}-\d{2}-\d{2}$/.test(value)
}

export default async function AuditingPage({ params, searchParams }: pageProps) {
    const { propertyId } = await params

    const property = await getPropertyForUser(propertyId)
    if (!property) redirect("/auth/login")

    const supabase = await createClient()
    const {
        data: { user },
    } = await supabase.auth.getUser()
    if (!user) redirect("/auth/login")
    const navVisibility = await resolveDashboardNavVisibility(supabase, propertyId, user.id)
    if (!navVisibility.moduleNavVisible.auditing) {
        redirect(`/dashboard/${propertyId}/access-denied`)
    }

    const sp = await searchParams

    const currentPage = Number.isNaN(Number(sp.page)) || !sp.page ? 1 : Math.max(1, Number(sp.page))
    const parsedPageSize =
        Number.isNaN(Number(sp.pageSize)) || !sp.pageSize ? undefined : Number(sp.pageSize)
    const pageSize = parsedPageSize && parsedPageSize > 0 ? parsedPageSize : 50

    const q = typeof sp.q === "string" ? sp.q : ""
    const action = typeof sp.action === "string" ? sp.action : "all"
    const resource = typeof sp.resource === "string" ? sp.resource : "all"

    const rawFrom = typeof sp.dateFrom === "string" ? sp.dateFrom : ""
    const rawTo = typeof sp.dateTo === "string" ? sp.dateTo : ""
    const dateFrom = isValidYmd(rawFrom) ? rawFrom : ""
    const dateTo = isValidYmd(rawTo) ? rawTo : ""

    type SortByOption = 'displayId' | 'action' | 'resource' | 'userDisplayName' | 'createdAt' | 'details'
    type SortOrderOption = 'asc' | 'desc'

    const validSortByOptions: readonly SortByOption[] = ['displayId', 'action', 'resource', 'userDisplayName', 'createdAt', 'details']
    const validSortOrderOptions: readonly SortOrderOption[] = ['asc', 'desc']

    const rawSortBy = typeof sp.sortBy === "string" ? sp.sortBy : "createdAt"
    const rawSortOrder = typeof sp.sortOrder === "string" ? sp.sortOrder : "desc"

    const sortBy: SortByOption = validSortByOptions.includes(rawSortBy as SortByOption) ? (rawSortBy as SortByOption) : "createdAt"
    const sortOrder: SortOrderOption = validSortOrderOptions.includes(rawSortOrder as SortOrderOption) ? (rawSortOrder as SortOrderOption) : "desc"

    const [{ data: activityLogs, total }, resourceOptions] = await Promise.all([
        getPropertyActivityLogs(
            propertyId,
            currentPage,
            pageSize,
            {
                search: q || null,
                action: action || null,
                resource: resource || null,
                dateFrom: dateFrom || null,
                dateTo: dateTo || null,
                sortBy,
                sortOrder,
            }
        ),
        getPropertyActivityLogResources(propertyId),
    ])

    return (
        <div className="space-y-2">
            <AuditingPageHeader propertyId={propertyId} />
            <AuditingFilter
                propertyId={propertyId}
                defaultSearch={q}
                defaultAction={action}
                defaultResource={resource}
                defaultDateFrom={dateFrom}
                defaultDateTo={dateTo}
                resourceOptions={resourceOptions}
            />
            <AuditingTable
                propertyId={propertyId}
                activityLogs={activityLogs}
                currentPage={currentPage}
                pageSize={pageSize}
                total={total}
                sortBy={sortBy}
                sortOrder={sortOrder}
            />
        </div>
    )
}

"use client"

import { useTransition } from "react"
import { usePathname, useRouter, useSearchParams } from "next/navigation"
import { ArrowDown, ArrowUp, ArrowUpDown } from "lucide-react"
import { Table, TableHeader, TableRow, TableHead, TableBody, TableCell } from "@/components/ui/table"
import { Pagination } from "@/components/ui/pagination"
import { PageSizeSelector } from "@/components/ui/page-size-selector"
import { type DashboardActivityLog } from "@/lib/dashboard/queries"

function formatDate(dateString: string): string {
    return new Date(dateString).toLocaleDateString("en-US", {
        month: "short",
        day: "numeric",
        year: "numeric",
    })
}

type SortColumn = 'displayId' | 'action' | 'resource' | 'userDisplayName' | 'createdAt' | 'details'

type AuditingTableProps = {
    propertyId: string
    activityLogs: DashboardActivityLog[] | null
    currentPage: number
    pageSize: number
    total: number
    sortBy: SortColumn
    sortOrder: 'asc' | 'desc'
}

export default function AuditingTable({
    propertyId: _propertyId,
    activityLogs,
    currentPage,
    pageSize,
    total,
    sortBy,
    sortOrder,
}: AuditingTableProps) {
    const router = useRouter()
    const pathname = usePathname()
    const searchParams = useSearchParams()
    const [isPending, startTransition] = useTransition()
    const rows = activityLogs ?? []

    const totalPages = Math.max(1, Math.ceil(total / pageSize))
    const clampedCurrentPage = Math.min(Math.max(currentPage, 1), totalPages)
    const startIndex = total === 0 ? 0 : (clampedCurrentPage - 1) * pageSize + 1
    const endIndex = Math.min(total, clampedCurrentPage * pageSize)

    const buildPageHref = (page: number) => {
        const params = new URLSearchParams(searchParams.toString())
        params.set("page", String(page))
        params.set("pageSize", String(pageSize))
        params.set("sortBy", sortBy)
        params.set("sortOrder", sortOrder)
        const q = params.toString()
        return q ? `${pathname}?${q}` : pathname
    }

    const goToPage = (page: number) => {
        startTransition(() => {
            router.push(buildPageHref(page))
        })
    }
    const handlePageSizeChange = (nextPageSize: number) => {
        startTransition(() => {
            const params = new URLSearchParams(searchParams.toString())
            params.set("page", "1")
            params.set("pageSize", String(nextPageSize))
            params.set("sortBy", sortBy)
            params.set("sortOrder", sortOrder)
            const q = params.toString()
            router.push(q ? `${pathname}?${q}` : pathname)
        })
    }
    const getDefaultSortOrder = (column: SortColumn): 'asc' | 'desc' => {
        if (column === 'displayId' || column === 'createdAt') return 'desc'
        return 'asc'
    }
    const handleSort = (column: SortColumn) => {
        const nextSortOrder =
            sortBy === column
                ? (sortOrder === 'asc' ? 'desc' : 'asc')
                : getDefaultSortOrder(column)

        startTransition(() => {
            const params = new URLSearchParams(searchParams.toString())
            params.set("page", "1")
            params.set("pageSize", String(pageSize))
            params.set("sortBy", column)
            params.set("sortOrder", nextSortOrder)
            const q = params.toString()
            router.push(q ? `${pathname}?${q}` : pathname)
        })
    }
    const SortIcon = ({ column }: { column: SortColumn }) => {
        if (sortBy !== column) return <ArrowUpDown className="h-3.5 w-3.5" />
        return sortOrder === 'asc' ? (
            <ArrowUp className="h-3.5 w-3.5" />
        ) : (
            <ArrowDown className="h-3.5 w-3.5" />
        )
    }
    return (
        <div className="hidden md:block">
            <div className="border border-border/80 bg-card/50">
                <Table className="text-xs">
                    <TableHeader className="sticky top-0 z-10 bg-red-50 dark:bg-red-950/30 uppercase">
                        <TableRow className="h-8 hover:bg-transparent data-[state=selected]:bg-transparent">
                            <TableHead className="py-1.5 dark:text-white/90 text-black/90 font-medium">
                                <button
                                    type="button"
                                    className="inline-flex items-center gap-1 hover:text-black/70 dark:hover:text-white/70"
                                    onClick={() => handleSort('displayId')}
                                >
                                    ID
                                    <SortIcon column="displayId" />
                                </button>
                            </TableHead>
                            <TableHead className="py-1.5 dark:text-white/90 text-black/90 font-medium">
                                <button
                                    type="button"
                                    className="inline-flex items-center gap-1 hover:text-black/70 dark:hover:text-white/70"
                                    onClick={() => handleSort('action')}
                                >
                                    Action
                                    <SortIcon column="action" />
                                </button>
                            </TableHead>
                            <TableHead className="py-1.5 dark:text-white/90 text-black/90 font-medium">
                                <button
                                    type="button"
                                    className="inline-flex items-center gap-1 hover:text-black/70 dark:hover:text-white/70"
                                    onClick={() => handleSort('resource')}
                                >
                                    Resource
                                    <SortIcon column="resource" />
                                </button>
                            </TableHead>
                            <TableHead className="py-1.5 dark:text-white/90 text-black/90 font-medium">
                                <button
                                    type="button"
                                    className="inline-flex items-center gap-1 hover:text-black/70 dark:hover:text-white/70"
                                    onClick={() => handleSort('userDisplayName')}
                                >
                                    User
                                    <SortIcon column="userDisplayName" />
                                </button>
                            </TableHead>
                            <TableHead className="py-1.5 dark:text-white/90 text-black/90 font-medium">
                                <button
                                    type="button"
                                    className="inline-flex items-center gap-1 hover:text-black/70 dark:hover:text-white/70"
                                    onClick={() => handleSort('createdAt')}
                                >
                                    Date
                                    <SortIcon column="createdAt" />
                                </button>
                            </TableHead>
                            <TableHead className="py-1.5 dark:text-white/90 text-black/90 font-medium">
                                <button
                                    type="button"
                                    className="inline-flex items-center gap-1 hover:text-black/70 dark:hover:text-white/70"
                                    onClick={() => handleSort('details')}
                                >
                                    Details
                                    <SortIcon column="details" />
                                </button>
                            </TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {rows.map((activityLog) => {
                            const formattedDate = formatDate(activityLog.createdAt)
                            return (
                                <TableRow key={activityLog.rowId}>
                                    <TableCell className="py-1.5">{activityLog.displayId}</TableCell>
                                    <TableCell className="py-1.5">{activityLog.action}</TableCell>
                                    <TableCell className="py-1.5">{activityLog.resource}</TableCell>
                                    <TableCell className="py-1.5">{activityLog.userDisplayName}</TableCell>
                                    <TableCell className="py-1.5">{formattedDate}</TableCell>
                                    <TableCell className="py-1.5">{activityLog.details}</TableCell>
                                </TableRow>
                            )
                        })}
                    </TableBody>
                </Table>
            </div>
            <div className="mt-3 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                <div className="flex w-full flex-col items-center gap-2 text-xs text-muted-foreground sm:w-auto sm:flex-row sm:items-center sm:gap-4">
                    <div>
                        Showing{" "}
                        <span className="font-medium">
                            {startIndex}–{endIndex}
                        </span>{" "}
                        of <span className="font-medium">{total}</span> activities
                    </div>
                    <PageSizeSelector
                        value={pageSize}
                        onChange={handlePageSizeChange}
                        disabled={isPending}
                    />
                </div>
                <div className="flex w-full justify-center sm:w-auto sm:justify-end">
                    <Pagination
                        currentPage={clampedCurrentPage}
                        totalPages={totalPages}
                        onPageChange={goToPage}
                        disabled={isPending}
                        windowSize={2}
                    />
                </div>
            </div>
        </div>
    )
}

}

